function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function numberOrDefault(value, fallback = 1) {
 const n = Number(value);
 return Number.isFinite(n) && n > 0 ? n : fallback;
}

function inferProductFromMemory(sessionMemory) {
 if (!sessionMemory?.usable) return {};

 const reference = sessionMemory.reference_context || {};
 const commercial = sessionMemory.commercial_context || {};

 if (Array.isArray(reference.current_focus_products) && reference.current_focus_products.length > 0) {
   return reference.current_focus_products[0] || {};
 }

 if (Array.isArray(commercial.last_products_recommended) && commercial.last_products_recommended.length > 0) {
   return commercial.last_products_recommended[0] || {};
 }

 if (reference.current_focus_product) {
   return {
     display_name: reference.current_focus_product
   };
 }

 if (commercial.last_product_consulted) {
   return {
     display_name: commercial.last_product_consulted
   };
 }

 return {};
}

const input = items[0]?.json || {};
const config = input.m5_config || {};

const trace = input.trace || {};
const context = input.context || {};
const currentInput = input.input || input.message || {};
const decision = input.decision || {};
const extracted = input.extracted || {};
const sessionMemory = input.session_memory || {};

const memoryProduct = inferProductFromMemory(sessionMemory);

const productId = clean(
 extracted.product_id ||
 extracted.product_candidate_id ||
 extracted.sku ||
 memoryProduct.product_id ||
 memoryProduct.sku
);

const sku = clean(
 extracted.sku ||
 extracted.product_id ||
 memoryProduct.sku ||
 memoryProduct.product_id
);

const productName = clean(
 extracted.product_name ||
 extracted.product_candidate ||
 memoryProduct.display_name ||
 memoryProduct.product_name
);

const category = clean(
 extracted.category_candidate ||
 memoryProduct.category
);

const quantity = numberOrDefault(
 extracted.quantity,
 config.demo_policy?.default_quantity || 1
);

const m5Request = {
 schema_version:
   input.schema_version ||
   config.contracts?.request_schema_version ||
   'dalia.m2_to_m5.commerce_request.v1',

 operation: clean(input.operation || 'process_commerce_turn'),

 trace: {
   event_id: clean(trace.event_id),
   conversation_id: clean(trace.conversation_id),
   session_id: clean(trace.session_id)
 },

 context: {
   environment: clean(context.environment || 'demo'),
   business_id: clean(context.business_id || 'business_demo'),
   channel: clean(context.channel || 'whatsapp'),
   user_id: clean(context.user_id),
   display_name: clean(context.display_name)
 },

 input: {
   message_id: clean(currentInput.message_id || currentInput.id),
   type: clean(currentInput.type || 'text'),
   text: clean(currentInput.text || currentInput.normalized_text),
   timestamp: clean(currentInput.timestamp)
 },

 decision: {
   intent: clean(decision.intent),
   commercial_stage: clean(decision.commercial_stage),
   reason: clean(decision.reason)
 },

 product: {
   product_id: productId,
   sku,
   product_name: productName,
   category,
   quantity
 },

 extracted: {
   ...extracted
 },

 session_memory: sessionMemory
};

return [
 {
   json: {
     ...input,
     m5_request: m5Request
   }
 }
];

function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const request = input.m5_request || {};

const errors = [];
const warnings = [];

if (request.operation !== 'process_commerce_turn') {
 errors.push('unsupported_operation');
}

if (isEmpty(request.context?.user_id)) {
 errors.push('missing_user_id');
}

if (isEmpty(request.trace?.session_id)) {
 warnings.push('missing_session_id');
}

if (request.decision?.intent !== 'purchase_intent') {
 warnings.push('intent_is_not_purchase_intent');
}

if (
 isEmpty(request.product?.product_id) &&
 isEmpty(request.product?.sku)
) {
 errors.push('missing_product_id_or_sku_for_transaction');
}

if (isEmpty(request.product?.product_name)) {
 warnings.push('missing_product_name');
}

if (Number(request.product?.quantity || 0) <= 0) {
 warnings.push('invalid_quantity_defaulting_to_one');
}

return [
 {
   json: {
     ...input,
     m5_validation: {
       valid: errors.length === 0,
       errors,
       warnings
     }
   }
 }
];

const base = $('Normalize M5 Request').first().json || {};
const config = base.m5_config || {};
const openStatuses = config.open_statuses || [];

const rows = items
 .map(item => item.json || {})
 .filter(row => row.transaction_id)
 .filter(row => openStatuses.includes(row.status));

rows.sort((a, b) => {
 const ad = new Date(a.updated_at || a.created_at || 0).getTime();
 const bd = new Date(b.updated_at || b.created_at || 0).getTime();
 return bd - ad;
});

const existingTransaction = rows[0] || null;

return [
 {
   json: {
     ...base,
     existing_transaction: existingTransaction,
     existing_transaction_lookup: {
       found: Boolean(existingTransaction),
       open_transactions_found: rows.length
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function hasAny(text, terms) {
 const normalized = clean(text).toLowerCase();
 return terms.some(term => normalized.includes(term));
}

const input = items[0]?.json || {};
const config = input.m5_config || {};
const request = input.m5_request || {};
const existing = input.existing_transaction || null;

const userText = request.input?.text || '';

const paymentConfirmationSignals = [
 'ya pague',
 'ya pagué',
 'pague',
 'pagué',
 'listo el pago',
 'ya hice el pago',
 'pago realizado'
];

let currentStatus = existing?.status || 'purchase_intent';
let action = '';

if (!existing) {
 action = 'start_purchase';
} else if (
 existing.status === 'payment_pending' &&
 hasAny(userText, paymentConfirmationSignals)
) {
 action = 'confirm_payment';
} else {
 action =
   config.action_by_status?.[existing.status] ||
   'fallback';
}

const commerceState = {
 has_open_transaction: Boolean(existing),
 transaction_id: existing?.transaction_id || '',
 current_status: currentStatus,
 next_action: action,

 product: {
   product_id:
     existing?.product_id ||
     request.product?.product_id ||
     request.product?.sku ||
     '',
   sku:
     existing?.sku ||
     request.product?.sku ||
     request.product?.product_id ||
     '',
   product_name:
     existing?.product_name ||
     request.product?.product_name ||
     '',
   category:
     existing?.category ||
     request.product?.category ||
     '',
   quantity:
     Number(existing?.quantity || request.product?.quantity || 1)
 },

 customer: {
   customer_name: existing?.customer_name || '',
   customer_city: existing?.customer_city || '',
   customer_address: existing?.customer_address || '',
   customer_notes: existing?.customer_notes || ''
 }
};

return [
 {
   json: {
     ...input,
     commerce_state: commerceState
   }
 }
];

