function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function safeNumber(value, fallback = 0) {
 const n = Number(value);
 return Number.isFinite(n) ? n : fallback;
}

function safeQuantity(value, fallback = 1) {
 const n = Number(value);
 return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const request = input.m5_request || {};
const config = input.m5_config || {};

const now = new Date().toISOString();

const productId = clean(
 request.product?.product_id ||
 request.product?.sku
);

const sku = clean(
 request.product?.sku ||
 request.product?.product_id
);

const quantity = safeQuantity(
 request.product?.quantity,
 config.demo_policy?.default_quantity || 1
);

const amount = safeNumber(
 request.extracted?.amount ||
 request.extracted?.price ||
 request.product?.amount ||
 0,
 0
);

const currency =
 clean(request.extracted?.currency) ||
 config.demo_policy?.currency ||
 'COP';

/**
* Decisión:
* Creamos la transacción directamente en data_required porque,
* después de reconocer intención de compra, el siguiente estado operativo
* es pedir los datos mínimos faltantes.
*
* Para no perder la evidencia de purchase_intent, la dejamos en metadata.status_history.
*/
const transactionId = makeId('txn_demo');

const transactionDraft = {
 transaction_id: transactionId,

 conversation_id: clean(request.trace?.conversation_id),
 session_id: clean(request.trace?.session_id),
 user_id: clean(request.context?.user_id),
 channel: clean(request.context?.channel || 'whatsapp'),
 display_name: clean(request.context?.display_name),

 product_id: productId,
 sku,
 product_name: clean(request.product?.product_name),
 category: clean(request.product?.category),
 quantity,

 amount,
 currency,

 status: 'data_required',

 customer_name: '',
 customer_city: clean(request.extracted?.city || ''),
 customer_address: '',
 customer_notes: '',

 stock_status: '',
 stock_available: null,
 stock_checked_at: null,

 payment_method: '',
 payment_status: '',
 payment_reference: '',
 payment_url: '',
 payment_confirmed_at: null,

 order_id: '',
 order_confirmed_at: null,

 shipment_id: '',
 tracking_code: '',
 tracking_url: '',
 shipment_status: '',
 shipment_created_at: null,

 last_user_message: clean(request.input?.text),

 metadata: {
   demo_mode: true,
   source_module: 'M5',
   source_operation: 'start_purchase',
   initial_intent: request.decision?.intent || 'purchase_intent',
   commercial_stage: request.decision?.commercial_stage || 'intent',
   memory_resolved: Boolean(request.extracted?.memory_resolved),
   memory_resolution: request.extracted?.memory_resolution || null,
   status_history: [
     {
       status: 'purchase_intent',
       at: now,
       reason: 'user_confirmed_purchase_intent'
     },
     {
       status: 'data_required',
       at: now,
       reason: 'minimum_customer_data_required'
     }
   ]
 },

 created_at: now
};

return [
 {
   json: {
     ...input,
     correlation: {
       ...(input.correlation || {}),
       transaction_id: transactionId
     },
     transaction_draft: transactionDraft
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function currencyFormat(amount, currency = 'COP') {
 const n = Number(amount || 0);

 if (!Number.isFinite(n) || n <= 0) {
   return '';
 }

 try {
   return new Intl.NumberFormat('es-CO', {
     style: 'currency',
     currency,
     maximumFractionDigits: 0
   }).format(n);
 } catch (e) {
   return `${currency} ${n}`;
 }
}

const base = $('Build Transaction Draft').first().json || {};
const transaction = base.transaction_draft || {};
const request = base.m5_request || {};
const config = base.m5_config || {};

const missingFields = [];

if (!clean(transaction.customer_name)) {
 missingFields.push('nombre');
}

if (!clean(transaction.customer_city)) {
 missingFields.push('ciudad');
}

if (!clean(transaction.customer_address)) {
 missingFields.push('dirección o zona de entrega');
}

const productName =
 clean(transaction.product_name) ||
 'el producto seleccionado';

const amountText = currencyFormat(transaction.amount, transaction.currency);

let replyText = `Perfecto, puedo ayudarte a simular la compra de ${productName}.`;

if (amountText) {
 replyText += ` El valor demo registrado es ${amountText}.`;
}

replyText += ` Para continuar, necesito ${missingFields.join(', ')}.`;

replyText += ` Recuerda que esta es una simulación de compra para la demo y no procesa pagos reales.`;

const nextStep = 'collect_minimum_data';

const m7Output = {
 schema_version: 'dalia.m5_to_m7.v1',
 trace: request.trace || {},
 channel: {
   name: request.context?.channel || 'whatsapp',
   user_id: request.context?.user_id || '',
   display_name: request.context?.display_name || ''
 },
 message: {
   replyText,
   response_type: 'commerce_data_required',
   next_step: nextStep
 },
 presentation: {
   sendImage: false,
   image_mode: 'none',
   image_candidates: []
 },
 catalog: {
   used_catalog: true,
   matched: true,
   match_type: 'product',
   items: [
     {
       product_id: transaction.product_id,
       sku: transaction.sku,
       display_name: transaction.product_name,
       category: transaction.category
     }
   ]
 },
 control: {
   can_continue: true,
   fallback_reason: null
 }
};

const m4Output = {
 schema_version: 'dalia.m5_to_m4.memory_update.v1',
 memory_update: {
   conversation_id: transaction.conversation_id,
   session_id: transaction.session_id,
   user_id: transaction.user_id,
   channel: transaction.channel,
   display_name: transaction.display_name,

   intent: 'purchase_intent',
   advisor_mode: 'commerce_lite',
   last_user_message: transaction.last_user_message,
   response_type: 'commerce_data_required',
   next_step: 'collect_minimum_data',

   product_consulted: transaction.product_name,
   last_products_recommended: [
     {
       product_id: transaction.product_id,
       sku: transaction.sku,
       display_name: transaction.product_name,
       category: transaction.category
     }
   ],

   category_consulted: transaction.category,
   preference_detected: 'compra iniciada',
   city_detected: transaction.customer_city || '',

   catalog_matched: true,
   purchase_signal_detected: true,
   handoff_suggested: false,

   updated_at: new Date().toISOString()
 }
};

const m8Output = {
 schema_version: 'dalia.m5_to_m8.event.v1',
 event: {
   event_name: 'commerce_transaction_started',
   module: 'M5',
   timestamp: new Date().toISOString(),
   trace: request.trace || {},
   context: request.context || {},
   commerce: {
     transaction_id: transaction.transaction_id,
     status: transaction.status,
     product_id: transaction.product_id,
     sku: transaction.sku,
     product_name: transaction.product_name,
     quantity: transaction.quantity,
     amount: transaction.amount,
     currency: transaction.currency
   },
   next_step: 'collect_minimum_data'
 }
};

return [
 {
   json: {
     ...base,
     minimum_data_request: {
       missing_fields: missingFields,
       next_step: nextStep
     },
     m7_output: m7Output,
     m4_output: m4Output,
     m8_output: m8Output
   }
 }
];

const input = items[0]?.json || {};
const transaction = input.transaction_draft || {};

return [
 {
   json: {
     schema_version: 'dalia.m5.commerce_result.v1',
     success: true,
     result_type: 'commerce_data_required',

     commerce: {
       transaction_id: transaction.transaction_id || '',
       status: transaction.status || 'data_required',
       product_id: transaction.product_id || '',
       sku: transaction.sku || '',
       product_name: transaction.product_name || '',
       category: transaction.category || '',
       quantity: transaction.quantity || 1,
       amount: transaction.amount || 0,
       currency: transaction.currency || 'COP',
       missing_fields: input.minimum_data_request?.missing_fields || []
     },

     m7_output: input.m7_output,
     m4_output: input.m4_output,
     m8_output: input.m8_output,

     control: {
       next_expected_action: 'collect_minimum_data',
       requires_user_response: true,
       demo_mode: true
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function firstMatch(text, patterns) {
 for (const pattern of patterns) {
   const match = text.match(pattern);
   if (match && match[1]) {
     return clean(match[1])
       .replace(/[.,;]+$/g, '')
       .trim();
   }
 }
 return '';
}

function extractQuantity(text) {
 const normalized = normalize(text);

 const match = normalized.match(/\b(\d{1,2})\s*(unidad|unidades|productos|termos|kits|cepillos)?\b/);
 if (!match) return null;

 const qty = Number(match[1]);
 if (!Number.isFinite(qty) || qty <= 0) return null;

 return Math.floor(qty);
}

function extractName(text) {
 return firstMatch(text, [
   /(?:me llamo|mi nombre es|soy|nombre[:\-])\s+([^,;\n]+)/i
 ]);
}

function extractCity(text) {
 const explicit = firstMatch(text, [
   /(?:ciudad[:\-]|estoy en|vivo en|me encuentro en|ubicado en|ubicada en)\s+([^,;\n]+)/i
 ]);

 if (explicit) return explicit;

 // Para demo: ciudades frecuentes. Puedes ampliar esta lista según el negocio.
 const knownCities = [
   'bogotá',
   'bogota',
   'medellín',
   'medellin',
   'cali',
   'barranquilla',
   'cartagena',
   'madrid',
   'chía',
   'chia',
   'soacha'
 ];

 const normalized = normalize(text);

 for (const city of knownCities) {
   if (normalized.includes(normalize(city))) {
     return city;
   }
 }

 return '';
}

function extractAddress(text) {
 const explicit = firstMatch(text, [
   /(?:dirección|direccion|dir|entrega en|enviar a|envío a|envio a|zona de entrega[:\-]?)\s+([^;\n]+)/i
 ]);

 if (explicit) return explicit;

 const addressSignals = [
   'calle',
   'carrera',
   'cra',
   'cll',
   'avenida',
   'av',
   'transversal',
   'diagonal',
   'barrio',
   'conjunto',
   'apartamento',
   'apto',
   '#'
 ];

 const lower = normalize(text);

 if (addressSignals.some(signal => lower.includes(normalize(signal)))) {
   return clean(text);
 }

 return '';
}

const input = items[0]?.json || {};
const request = input.m5_request || {};
const existing = input.existing_transaction || {};
const extracted = request.extracted || {};

const userText = clean(request.input?.text);

const extractedPurchaseData = {
 customer_name:
   clean(extracted.customer_name) ||
   clean(extracted.name) ||
   extractName(userText),

 customer_city:
   clean(extracted.customer_city) ||
   clean(extracted.city) ||
   extractCity(userText),

 customer_address:
   clean(extracted.customer_address) ||
   clean(extracted.address) ||
   extractAddress(userText),

 customer_notes:
   clean(extracted.customer_notes) ||
   clean(extracted.notes),

 quantity:
   extractQuantity(userText) ||
   Number(extracted.quantity || existing.quantity || request.product?.quantity || 1)
};

return [
 {
   json: {
     ...input,
     extracted_purchase_data: extractedPurchaseData
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function preferNew(newValue, oldValue) {
 const value = clean(newValue);
 return value ? value : clean(oldValue);
}

function safeQuantity(newQty, oldQty) {
 const n = Number(newQty);
 if (Number.isFinite(n) && n > 0) return Math.floor(n);

 const old = Number(oldQty);
 if (Number.isFinite(old) && old > 0) return Math.floor(old);

 return 1;
}

const input = items[0]?.json || {};
const existing = input.existing_transaction || {};
const extracted = input.extracted_purchase_data || {};
const config = input.m5_config || {};

const mergedCustomerData = {
 customer_name: preferNew(extracted.customer_name, existing.customer_name),
 customer_city: preferNew(extracted.customer_city, existing.customer_city),
 customer_address: preferNew(extracted.customer_address, existing.customer_address),
 customer_notes: preferNew(extracted.customer_notes, existing.customer_notes),
 quantity: safeQuantity(extracted.quantity, existing.quantity)
};

const requiredFields =
 config.required_customer_fields || [
   'customer_name',
   'customer_city',
   'customer_address'
 ];

const missingFields = [];

for (const field of requiredFields) {
 if (!clean(mergedCustomerData[field])) {
   missingFields.push(field);
 }
}

const fieldLabels = {
 customer_name: 'nombre',
 customer_city: 'ciudad',
 customer_address: 'dirección o zona de entrega'
};

const missingFieldLabels = missingFields.map(field => fieldLabels[field] || field);

const complete = missingFields.length === 0;

return [
 {
   json: {
     ...input,
     merged_customer_data: mergedCustomerData,
     minimum_data_validation: {
       complete,
       missing_fields: missingFields,
       missing_field_labels: missingFieldLabels,
       required_fields: requiredFields
     }
   }
 }
