function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function firstMatch(text, patterns) {
 for (const pattern of patterns) {
   const match = text.match(pattern);
   if (match && match[1]) {
     return clean(match[1])
       .replace(/[.,;]+$/g, '')
       .trim();
   }
 }
 return '';
}

function extractQuantity(text) {
 const normalized = normalize(text);

 const match = normalized.match(/\b(\d{1,2})\s*(unidad|unidades|productos|termos|kits|cepillos)?\b/);
 if (!match) return null;

 const qty = Number(match[1]);
 if (!Number.isFinite(qty) || qty <= 0) return null;

 return Math.floor(qty);
}

function extractName(text) {
 return firstMatch(text, [
   /(?:me llamo|mi nombre es|soy|nombre[:\-])\s+([^,;\n]+)/i
 ]);
}

function extractCity(text) {
 const explicit = firstMatch(text, [
   /(?:ciudad[:\-]|estoy en|vivo en|me encuentro en|ubicado en|ubicada en)\s+([^,;\n]+)/i
 ]);

 if (explicit) return explicit;

 // Para demo: ciudades frecuentes. Puedes ampliar esta lista según el negocio.
 const knownCities = [
   'bogotá',
   'bogota',
   'medellín',
   'medellin',
   'cali',
   'barranquilla',
   'cartagena',
   'madrid',
   'chía',
   'chia',
   'soacha'
 ];

 const normalized = normalize(text);

 for (const city of knownCities) {
   if (normalized.includes(normalize(city))) {
     return city;
   }
 }

 return '';
}

function extractAddress(text) {
 const explicit = firstMatch(text, [
   /(?:dirección|direccion|dir|entrega en|enviar a|envío a|envio a|zona de entrega[:\-]?)\s+([^;\n]+)/i
 ]);

 if (explicit) return explicit;

 const addressSignals = [
   'calle',
   'carrera',
   'cra',
   'cll',
   'avenida',
   'av',
   'transversal',
   'diagonal',
   'barrio',
   'conjunto',
   'apartamento',
   'apto',
   '#'
 ];

 const lower = normalize(text);

 if (addressSignals.some(signal => lower.includes(normalize(signal)))) {
   return clean(text);
 }

 return '';
}

