// Determinar qué tipo de memoria corresponde según el nodo de origen
const cityDetected = clean(tx.city || tx.delivery_city);
const orderConfirmed = clean(tx.status) === 'order_confirmed';

const memoryType = orderConfirmed ? 'purchase_context' : 'city_or_location';

const memoryText = orderConfirmed
