function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

const input = items[0]?.json || {};

const request  = input.m5_request          || {};
const existing = input.existing_transaction || {};
const demoOrder = input.demo_order          || {};

// merged_customer_data existe en punto 1, existing en punto 2
const mergedData = input.merged_customer_data || {};

const ctx   = request.context || {};
const trace = request.trace   || {};

// Determinar qué tipo de memoria corresponde
// según qué nodo disparó este payload
const orderConfirmed = clean(demoOrder.order_id) !== '';
const cityCollected  = clean(mergedData.customer_city || existing.customer_city) !== '';

const memoryType = orderConfirmed
  ? 'purchase_context'
  : 'city_or_location';

const cityValue = clean(
  mergedData.customer_city ||
  existing.customer_city
);

const productName = clean(
  existing.product_name ||
  request.product?.product_name
);

const productId = clean(
  existing.product_id ||
  existing.sku ||
  request.product?.product_id ||
  request.product?.sku
);

const category = clean(
  existing.category ||
  request.product?.category
);

// Construir memory_text_hint directamente acá
// para que M4 Build Customer Memory Text lo use si viene presente
let memoryTextHint = '';
if (orderConfirmed && productName) {
  memoryTextHint =
    `Cliente ${clean(ctx.user_id)} confirmó compra del producto ${productName}.` +
    (cityValue ? ` Ciudad de entrega: ${cityValue}.` : '');
} else if (cityCollected && cityValue) {
  memoryTextHint =
    `Cliente ${clean(ctx.user_id)} confirmó ${cityValue} como ciudad de entrega.` +
    (productName ? ` Producto en proceso: ${productName}.` : '');
}

return [
  {
    json: {
      schema_version: 'dalia.m5_to_m4.vector_save_request.v1',
      operation: 'save_vector_memory',
      context: {
        business_id:     clean(ctx.business_id)     || 'business_demo',
        user_id:         clean(ctx.user_id),
        channel:         clean(ctx.channel)          || 'whatsapp',
        conversation_id: clean(trace.conversation_id),
        session_id:      clean(trace.session_id)
      },
      turn: {
        user_message:            clean(request.input?.text),
        dalia_response:          '',
        intent:                  orderConfirmed ? 'purchase_intent' : 'product_search',
        memory_type_hint:        memoryType,
        memory_text_hint:        memoryTextHint,
        product_consulted:       productName  || null,
        product_id:              productId    || null,
        category:                category     || null,
        city_detected:           cityValue    || null,
        purchase_signal_detected: orderConfirmed,
        order_id:                clean(demoOrder.order_id) || null,
        handoff_suggested:       false
      }
    }
  }
];
